export const TEAR_EACH_HAND_SPEED = 0.35;
/** 線に沿った相対速度 (拡大縮小) が、垂直な相対速度のこの割合を超えたら、引き伸ばしと見なして破らない。 */
export const TEAR_MAX_ALONG_RATIO = 0.5;
/** 上の条件を満たし続ける時間 (秒)。手の速度は 1 フレームだけ跳ねることがあるので、少し続いたときだけ破る。 */
