  group: THREE.Group;
  side: -1 | 1;
  age: number;
  /** 下向きの速さ (m/s、写真のローカルではなくワールド) */
  fall: number;
  materials: THREE.MeshBasicMaterial[];
  textures: THREE.Texture[];
