  };

  return {
    id: 'D2',
    label: '破る',
    category: 'delete',
    disable() {
      for (const fragment of fragments) dispose(fragment);
      fragments.length = 0;
      sustained = 0;
      sustainedItem = null;
    },
    update(frame: FrameContext) {
